use vstd::prelude::*;

verus! {

    struct Interval {
        low:  f32,
        high: f32,
    }

    struct Laguerre {
        coefficients: Vec<f32>,
        domain:       Interval,
        window:       Interval,
    }

    // Construct a Laguerre series from an arbitrary Vec<f32>,
    // setting both domain and window to [0.0,1.0] exactly,
    // and preserving the full contents of the input vector.
    fn make_laguerre(coefficients: Vec<f32>) -> (lag: Laguerre)
        ensures
            // the returned vector has the same length
            lag.coefficients.len() == coefficients.len(),
            // and each entry is bitwise-equal to the input
            forall |i: usize| i < coefficients.len() ==>
                lag.coefficients[i] == coefficients[i],
            // both intervals are set to [0.0,1.0]
            lag.domain.low  == 0.0,
            lag.domain.high == 1.0,
            lag.window.low  == 0.0,
            lag.window.high == 1.0,
    {
        Laguerre {
            coefficients,
            domain: Interval { low:  0.0, high: 1.0 },
            window: Interval { low:  0.0, high: 1.0 },
        }
    }

    fn main() {
        // example usage; not necessary for verification
        let coeffs = Vec::from_slice(&[3.14_f32, 2.71, 1.0]);
        let lag = make_laguerre(coeffs);
        assert!(lag.domain.low == 0.0);
        assert!(lag.window.high == 1.0);
        assert!(lag.coefficients[0] == 3.14);
    }
}